//! Oracle tier: reads artifacts regenerated by `scripts/regen-fixtures.py`
//! (tools/fixtures/langlibelk-language-{public,url}.toml, docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
use d2_rs_core::{NodeId, Size, ast::Shared};
use d2_rs_language::{ParseOptions, compiler, parse};
use serde_json::Value;
use std::collections::HashMap;
fn bytes(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}
struct Unmeasured;
impl compiler::GraphMeasurer for Unmeasured {
    fn measure(&self, _: &str) -> Size {
        Size::default()
    }
}
fn verify(start: usize, end: usize) {
    let fixture: Value = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/public-measured-state-v090.json"
    ))
    .unwrap();
    let requests = fixture["requests"].as_array().unwrap();
    let source = fixture["source"].as_array().unwrap();
    assert_eq!(requests.len(), 604);
    assert_eq!(source.len(), 604);
    for (request, expected) in requests[start..end].iter().zip(&source[start..end]) {
        let parsed = parse(
            request["path"].as_str().unwrap(),
            &bytes(request["hex"].as_str().unwrap()),
            Some(ParseOptions {
                utf16_positions: request["utf16"].as_bool().unwrap(),
                errors: None,
            }),
        );
        assert!(parsed.error.is_none());
        let files = request["files_hex"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(k, v)| (k.clone(), bytes(v.as_str().unwrap())))
            .collect::<HashMap<_, _>>();
        let (c, root) = compiler::compile_ir_with_options(
            Shared::new(parsed.map),
            compiler::CompileOptions {
                utf16_positions: request["utf16"].as_bool().unwrap(),
                import_opener: Some(Box::new(move |path| {
                    files
                        .get(path)
                        .map(|b| {
                            Box::new(std::io::Cursor::new(b.clone()))
                                as Box<dyn d2_rs_language::stream::ByteReader>
                        })
                        .ok_or_else(|| format!("open {path}: file does not exist"))
                })),
            },
        )
        .unwrap();
        let (_, _, styles) =
            compiler::lower_graph_with_measurer_and_labels(&c, root, &Unmeasured).unwrap();
        let graph = compiler::lower_graph(&c, root).unwrap();
        assert_eq!(
            graph.nodes.len(),
            expected["nodes"].as_array().unwrap().len()
        );
        for object in expected["nodes"].as_array().unwrap() {
            let j = graph
                .nodes
                .iter()
                .position(|node| Some(node.external_id.as_str()) == object["id"].as_str())
                .unwrap();
            let id = NodeId(u32::try_from(j).unwrap());
            let node = &graph.nodes[j];
            assert_eq!(
                graph.node_label_bytes.get(&id).unwrap(),
                &bytes(object["label_hex"].as_str().unwrap()),
                "{request} label bytes"
            );
            for (actual, expected) in [node.size.width, node.size.height]
                .iter()
                .zip(object["size"].as_array().unwrap())
            {
                assert_eq!(*actual, expected.as_f64().unwrap(), "{request} size");
            }
            let size = node.label_size.unwrap_or_default();
            for (actual, expected) in [size.width, size.height]
                .iter()
                .zip(object["label_dimensions"].as_array().unwrap())
            {
                assert_eq!(
                    *actual,
                    expected.as_f64().unwrap(),
                    "{request} label dimensions"
                );
            }
            let style = serde_json::to_value(styles.get(&id).unwrap()).unwrap();
            let attrs = &object["attributes"];
            for (go, rust) in [
                ("fill", "fill"),
                ("fillPattern", "fill_pattern"),
                ("stroke", "stroke"),
                ("strokeWidth", "stroke_width"),
                ("opacity", "opacity"),
                ("strokeDash", "stroke_dash"),
                ("animated", "animated"),
                ("borderRadius", "border_radius"),
                ("shadow", "shadow"),
                ("3d", "three_dee"),
                ("multiple", "multiple"),
                ("doubleBorder", "double_border"),
                ("fontColor", "font_color"),
                ("font", "font"),
                ("textTransform", "text_transform"),
                ("filled", "filled"),
            ] {
                assert_eq!(
                    style[rust].as_str(),
                    attrs["style"][go]["value"].as_str(),
                    "{request} {go}"
                );
            }
            assert_eq!(style["language"].as_str(), attrs["language"].as_str());
            for key in ["link", "tooltip"] {
                assert_eq!(style[key].as_str(), attrs[key]["value"].as_str());
            }
        }
        assert_eq!(
            graph.edges.len(),
            expected["edges"].as_array().unwrap().len()
        );
        for (j, edge) in expected["edges"].as_array().unwrap().iter().enumerate() {
            let label = graph.edge_labels[j].as_ref();
            assert_eq!(
                label.map(|label| label.text.as_bytes()).unwrap_or_default(),
                bytes(edge["label_hex"].as_str().unwrap()),
                "{request} edge bytes"
            );
            let size = label.map(|label| label.size).unwrap_or_default();
            for (actual, expected) in [size.width, size.height]
                .iter()
                .zip(edge["label_dimensions"].as_array().unwrap())
            {
                assert_eq!(
                    *actual,
                    expected.as_f64().unwrap(),
                    "{request} edge dimensions"
                );
            }
        }
    }
}
#[test]
fn original_measurement_boundary_product() {
    verify(0, 476);
}

#[test]
fn original_class_header_language_and_italic_roles() {
    verify(476, 604);
}
